// Generate PKCE state + verifier + S256 challenge, build the Etsy OAuth
// authorisation URL. Reads ETSY_CLIENT_ID and ETSY_REDIRECT_URI from env.
const crypto = require('crypto');

const query = $input.first().json.query || {};
const shopName = (query.shop_name || query.name || '').trim();
if (!shopName) throw new Error('Provide ?shop_name=<your shop label>');

const clientId    = process.env.ETSY_CLIENT_ID;
const redirectUri = process.env.ETSY_REDIRECT_URI;
if (!clientId)    throw new Error('ETSY_CLIENT_ID is not set');
if (!redirectUri) throw new Error('ETSY_REDIRECT_URI is not set');

// PKCE values
const state         = crypto.randomBytes(16).toString('hex');
const codeVerifier  = crypto.randomBytes(48).toString('base64url');
const codeChallenge = crypto.createHash('sha256').update(codeVerifier).digest('base64url');

// Scope set: enough for listing publish (listings_w), order sync
// (transactions_r), and identifying the user (email_r).
const scope = 'email_r listings_w transactions_r';

const authUrl = 'https://www.etsy.com/oauth/connect?' + new URLSearchParams({
  response_type:         'code',
  client_id:             clientId,
  redirect_uri:          redirectUri,
  scope,
  state,
  code_challenge:        codeChallenge,
  code_challenge_method: 'S256'
}).toString();

return [{ json: { state, code_verifier: codeVerifier, redirect_uri: redirectUri, shop_name: shopName, auth_url: authUrl } }];
